'use client'

import { Menu as BaseMenu } from '@base-ui/react/menu'
import { Menubar as BaseMenubar } from '@base-ui/react/menubar'
import { cn } from '@/lib/utils'
import { MenuEntries, MenuSurface, type MenuEntry } from './Menu'
import styles from './Menubar.module.css'

export interface MenubarMenu {
  /** The top-level item: File, Edit, View. */
  label: string
  /** The flyout's entries, the same data as Menu's `items`. */
  items: MenuEntry[]
  disabled?: boolean
  /** Open this menu on first render, uncontrolled. */
  defaultOpen?: boolean
}

export interface MenubarProps {
  menus: MenubarMenu[]
  /** Names the bar. Needed when a page has more than one menubar. */
  'aria-label'?: string
  /**
   * While a flyout is open, lock page scroll and make the rest of the page
   * inert. `false` leaves the page as is.
   */
  isModal?: boolean
  /** Where the flyouts render instead of `<body>`, e.g. an element in fullscreen. */
  container?: HTMLElement | null
  className?: string
}

/** A row of menus, as in a desktop app: File, Edit, View, each opening a flyout. */
export function Menubar({ menus, 'aria-label': ariaLabel, isModal = true, container, className }: MenubarProps) {
  return (
    <BaseMenubar aria-label={ariaLabel} modal={isModal} className={cn(styles.bar, className)}>
      {menus.map((menu, i) => (
        <BaseMenu.Root key={i} disabled={menu.disabled} defaultOpen={menu.defaultOpen}>
          <BaseMenu.Trigger className={styles.trigger}>{menu.label}</BaseMenu.Trigger>
          <MenuSurface side="bottom" align="start" container={container}>
            <MenuEntries items={menu.items} />
          </MenuSurface>
        </BaseMenu.Root>
      ))}
    </BaseMenubar>
  )
}

/* The bar: a quiet strip on the page surface, triggers inset the same
   4px as the items inside a Menu popup, so a trigger's corner nests the
   same way. */
.bar {
  --menubar-inset: var(--space-stack);
  display: flex;
  align-items: center;
  gap: var(--space-0-5);
  inline-size: fit-content;
  max-inline-size: 100%;
  overflow-x: auto;
  padding: var(--menubar-inset);
  border: 1px solid var(--border);
  border-radius: var(--radius-field);
  background: var(--background);
  color: var(--foreground);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
}

/* A trigger is a row of tier sm: shorter than the md items in the flyout,
   so the bar stays a strip and not a toolbar of buttons. */
.trigger {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  block-size: var(--control-sm);
  padding: 0 var(--control-sm-pad);
  border: 0;
  border-radius: calc(var(--radius-field) - var(--menubar-inset));
  background: transparent;
  color: inherit;
  font: inherit;
  font-weight: 500;
  cursor: default;
  user-select: none;
  outline: none;
}

/* Hover, keyboard highlight and the open menu share the item highlight. */
.trigger:hover,
.trigger[data-highlighted],
.trigger[data-popup-open] {
  background: var(--accent);
  color: var(--accent-foreground);
}

.trigger:focus-visible {
  outline: var(--focus-width) solid var(--ring);
  outline-offset: calc(var(--focus-width) * -1);
}

.trigger[data-disabled] {
  background: transparent;
  color: var(--muted-foreground);
  opacity: 0.6;
}

/* Triggers are 24px; on touch the hit area grows to 44px without the
   strip growing. */
@media (pointer: coarse) {
  .trigger {
    position: relative;
  }
  .trigger::after {
    content: '';
    position: absolute;
    inset: 50% 0 auto;
    block-size: var(--target-coarse);
    translate: 0 -50%;
  }
}
